import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def ph(v):
    r = v
    p = 2
    while p * p <= v:
        if v % p == 0:
            while v % p == 0:
                v //= p
            r -= r // p
        p += 1
    if v > 1:
        r -= r // v
    return r
c = 0
for idx in range(n - 1):
    if ((a[idx] >= 2) & (ph(a[idx]) % 2 == 0)) and ((a[idx + 1] >= 2) & (ph(a[idx + 1]) % 2 == 0)):
        c += 1
print(c)

